c.python:
class Solution:
    def finalElement(self, nums: List[int]) -> int:
        return sorted(nums, reverse=True)[(len(nums) + 1) // 2 - 1]

c.cpp:
class Solution {
public:
    int finalElement(vector<int>& nums) {
        sort(nums.rbegin(), nums.rend());
        return nums[(nums.size() + 1) / 2 - 1];
    }
};

c.java:
class Solution {
    public int finalElement(int[] nums) {
        Arrays.sort(nums);
        return nums[nums.length - (nums.length + 1) / 2];
    }
}

c.javascript:
var finalElement = function(nums) {
    const a = [...nums].sort((x, y) => y - x);
    return a[Math.ceil(a.length / 2) - 1];
};
